import fs from 'node:fs/promises';
import path from 'node:path';

import { errorMessage } from '../../helpers.js';
import {
  buildOverlayRegistryForCheck,
  checkOpenApiFile,
  getOpenApiFilenamesFromDocsConfig,
  type OpenApiCheckMessage,
} from '../../openApiCheck.js';
import type { Finding, SiteRule } from '../types.js';

export const openApiSpec: SiteRule = {
  id: 'openapi-spec',
  group: 'openapi',
  severity: 'error',
  scope: 'site',
  description:
    "OpenAPI specs in docs.json or mint.json that don't parse or validate, with overlays applied",
  check: async (site) => {
    let filenames: string[] = [];
    try {
      const config = JSON.parse(
        await fs.readFile(path.join(site.baseDir, site.configFile), 'utf-8')
      );
      // mint.json lists its specs under a top-level openapi key
      filenames = getOpenApiFilenamesFromDocsConfig(
        site.configFile === 'mint.json' ? { api: { openapi: config.openapi } } : config
      );
    } catch {
      // A missing or invalid config file is the build's to report
    }
    if (filenames.length === 0) return [];

    let overlayRegistry;
    try {
      overlayRegistry = await buildOverlayRegistryForCheck(site.localSchema);
    } catch (error) {
      return [{ file: site.configFile, message: `OpenAPI overlays: ${errorMessage(error)}` }];
    }

    const perFile = await Promise.all(
      filenames.map(async (file) => {
        const messages: OpenApiCheckMessage[] = [];
        await checkOpenApiFile(file, site.localSchema, overlayRegistry, (message) =>
          messages.push(message)
        );
        return messages.flatMap(({ level, message }): Finding[] =>
          level === 'error'
            ? [{ file, message }]
            : level === 'warning'
              ? [{ file, message, severity: 'warning' }]
              : []
        );
      })
    );
    return perFile.flat();
  },
};
